using CrabShare.SettlementEngine;
using FsCheck;
using FsCheck.Fluent;
using FsCheck.Xunit;

namespace CrabShare.SettlementEngine.Tests;

/// <summary>
/// Ví dụ cách viết test cho quyết toán: một test thường (ví dụ cụ thể) và vài test thuộc tính (FsCheck sinh hàng trăm bộ số).
/// Phần nghiên cứu TSK-12 mở rộng thư mục này với đầy đủ bất biến và quan hệ metamorphic.
/// </summary>
public class LargestRemainderAllocatorTests
{
    [Fact]
    public void Chia_100_cho_3_nguoi_bang_nhau_tong_van_dung_100()
    {
        var shares = LargestRemainderAllocator.Allocate(100, [("A", 1L), ("B", 1L), ("C", 1L)]);

        Assert.Equal(100, shares.Sum(s => s.Amount));
        Assert.Equal([34L, 33L, 33L], shares.Select(s => s.Amount)); // hoà phần lẻ: mã nhỏ hơn (A) được trước
    }

    // Bất biến bảo toàn: tổng các phần luôn bằng số tiền đem chia, kể cả khi âm
    [Property]
    public Property Tong_cac_phan_bang_tong_dem_chia(long total, NonEmptyArray<PositiveInt> rawWeights)
    {
        var weights = rawWeights.Get.Select((w, i) => (i, (long)w.Get)).ToList();
        var shares = LargestRemainderAllocator.Allocate(total % 10_000_000_000, weights);
        return (shares.Sum(s => s.Amount) == total % 10_000_000_000).ToProperty();
    }

    // Không ai lệch quá 1 đồng so với phần chính xác theo tỷ lệ
    [Property]
    public Property Moi_phan_lech_khong_qua_1_dong(PositiveInt total, NonEmptyArray<PositiveInt> rawWeights)
    {
        var weights = rawWeights.Get.Select((w, i) => (i, (long)w.Get)).ToList();
        var sum = weights.Sum(w => (decimal)w.Item2);
        var shares = LargestRemainderAllocator.Allocate(total.Get, weights);
        return shares.Select((s, i) => Math.Abs(s.Amount - total.Get * weights[i].Item2 / sum) < 1m).All(x => x).ToProperty();
    }

    // Metamorphic: đổi thứ tự danh sách nhà đầu tư không làm đổi số tiền của từng người
    [Property]
    public Property Doi_thu_tu_nguoi_nhan_khong_doi_ket_qua(PositiveInt total, NonEmptyArray<PositiveInt> rawWeights)
    {
        var weights = rawWeights.Get.Select((w, i) => (i, (long)w.Get)).ToList();
        var a = LargestRemainderAllocator.Allocate(total.Get, weights).ToDictionary(s => s.Key, s => s.Amount);
        var b = LargestRemainderAllocator.Allocate(total.Get, weights.AsEnumerable().Reverse().ToList()).ToDictionary(s => s.Key, s => s.Amount);
        return a.All(kv => b[kv.Key] == kv.Value).ToProperty();
    }
}

using CrabShare.SettlementEngine;

namespace CrabShare.SettlementEngine.Tests;

public class MutationRegressionTests
{
    [Fact]
    public void Allocator_rejects_empty_recipients()
    {
        var error = Assert.Throws<ArgumentException>(() =>
            LargestRemainderAllocator.Allocate(10, Array.Empty<(long, long)>()));
        Assert.Equal("weights", error.ParamName);
    }

    [Theory]
    [InlineData(0)]
    [InlineData(-1)]
    public void Allocator_rejects_one_invalid_weight_among_valid_weights(long weight)
    {
        var error = Assert.Throws<ArgumentException>(() =>
            LargestRemainderAllocator.Allocate(10, [(1L, 10L), (2L, weight)]));
        Assert.Equal("weights", error.ParamName);
    }

    [Theory]
    [InlineData(2, 0, 2)]
    [InlineData(-2, 0, -2)]
    [InlineData(0, 0, 0)]
    public void Equal_remainders_favor_larger_capital_and_preserve_input_order(long total, long small, long large)
    {
        var shares = LargestRemainderAllocator.Allocate(total, [(2L, 3L), (1L, 1L)]);
        Assert.Equal([new Share<long>(2, large), new Share<long>(1, small)], shares);
    }

    [Fact]
    public void Settlement_rejects_empty_investors()
    {
        var error = Assert.Throws<ArgumentException>(() =>
            SettlementCalculator.Calculate(new(10, 0, 7, 5, [])));
        Assert.Equal("input", error.ParamName);
    }

    [Theory]
    [InlineData(0)]
    [InlineData(-1)]
    public void Settlement_rejects_one_invalid_capital_among_valid_investors(long capital)
    {
        var error = Assert.Throws<ArgumentException>(() =>
            SettlementCalculator.Calculate(new(10, 0, 7, 5, [(1, 10), (2, capital)])));
        Assert.Equal("input", error.ParamName);
    }

    [Fact]
    public void Settlement_rejects_duplicate_investor_ids()
    {
        var error = Assert.Throws<ArgumentException>(() =>
            SettlementCalculator.Calculate(new(10, 0, 7, 5, [(1, 10), (1, 20)])));
        Assert.Equal("input", error.ParamName);
    }

    [Theory]
    [InlineData(-1, 5)]
    [InlineData(101, 5)]
    [InlineData(7, -1)]
    [InlineData(7, 101)]
    public void Settlement_rejects_each_percentage_outside_zero_to_one_hundred(int operatorPct, int taxPct)
    {
        var error = Assert.Throws<ArgumentOutOfRangeException>(() =>
            SettlementCalculator.Calculate(new(10, 0, operatorPct, taxPct, [(1, 10)])));
        Assert.Equal("input", error.ParamName);
    }

    [Theory]
    [InlineData(0, 0, 0, 100, 0, 110)]
    [InlineData(100, 0, 100, 0, 0, 10)]
    [InlineData(0, 100, 0, 100, 100, 10)]
    [InlineData(100, 100, 100, 0, 0, 10)]
    public void Settlement_accepts_percentage_endpoints_and_returns_exact_amounts(
        int operatorPct, int taxPct, long remuneration, long profit, long tax, long payout)
    {
        var result = SettlementCalculator.Calculate(new(110, 10, operatorPct, taxPct, [(42, 10)]));
        Assert.Equal(100, result.RevenuePool);
        Assert.Equal(remuneration, result.OperatorRemuneration);
        Assert.Equal(profit, result.Distributable);
        Assert.Equal(0, result.UncoveredLoss);
        Assert.Equal(tax, result.TaxTotal);
        Assert.Equal(new SettlementLineResult(42, 10, profit, tax, payout), Assert.Single(result.Lines));
    }

    [Fact]
    public void Zero_pool_returns_capital_without_remuneration_or_tax()
    {
        var result = SettlementCalculator.Calculate(new(10, 10, 7, 5, [(2, 3), (1, 1)]));
        Assert.Equal(0, result.RevenuePool);
        Assert.Equal(0, result.OperatorRemuneration);
        Assert.Equal(0, result.Distributable);
        Assert.Equal(0, result.UncoveredLoss);
        Assert.Equal(0, result.TaxTotal);
        Assert.Equal([new SettlementLineResult(2, 3, 0, 0, 3), new SettlementLineResult(1, 1, 0, 0, 1)], result.Lines);
    }

    [Fact]
    public void Loss_above_largest_capital_but_below_total_does_not_wipe_out_every_investor()
    {
        var result = SettlementCalculator.Calculate(new(0, 60, 7, 5, [(1, 50), (2, 50)]));
        Assert.Equal(-60, result.Distributable);
        Assert.Equal(0, result.UncoveredLoss);
        Assert.Equal(0, result.OperatorRemuneration);
        Assert.Equal(0, result.TaxTotal);
        Assert.Equal([new SettlementLineResult(1, 50, -30, 0, 20), new SettlementLineResult(2, 50, -30, 0, 20)], result.Lines);
    }

    [Fact]
    public void Rounding_to_small_investors_capital_does_not_create_additional_loss()
    {
        var result = SettlementCalculator.Calculate(new(0, 101, 7, 5, [(1, 1), (2, 1), (3, 100)]));
        Assert.Equal(-101, result.Distributable);
        Assert.Equal(0, result.UncoveredLoss);
        Assert.Equal([new SettlementLineResult(1, 1, -1, 0, 0), new SettlementLineResult(2, 1, -1, 0, 0), new SettlementLineResult(3, 100, -99, 0, 1)], result.Lines);
    }

    [Fact]
    public void Loss_equal_to_total_capital_leaves_no_uncovered_loss()
    {
        var result = SettlementCalculator.Calculate(new(0, 100, 7, 5, [(1, 30), (2, 70)]));
        Assert.Equal(0, result.UncoveredLoss);
        Assert.Equal([new SettlementLineResult(1, 30, -30, 0, 0), new SettlementLineResult(2, 70, -70, 0, 0)], result.Lines);
    }

    [Theory]
    [InlineData(30_000_000_000, 0)]
    [InlineData(100_000_000_000, 70_000_000_000)]
    public void Large_loss_at_or_above_total_capital_uses_the_cap_without_proportional_multiplication(long cost, long uncovered)
    {
        var result = SettlementCalculator.Calculate(new(0, cost, 7, 5, [(1, 10_000_000_000), (2, 20_000_000_000)]));
        Assert.Equal(-cost, result.Distributable);
        Assert.Equal(uncovered, result.UncoveredLoss);
        Assert.Equal([
            new SettlementLineResult(1, 10_000_000_000, -10_000_000_000, 0, 0),
            new SettlementLineResult(2, 20_000_000_000, -20_000_000_000, 0, 0)
        ], result.Lines);
    }
}

using CrabShare.SettlementEngine;
using FsCheck;
using FsCheck.Fluent;
using FsCheck.Xunit;

namespace CrabShare.SettlementEngine.Tests;

/// <summary>TH-12: bảng quyết toán (TL-12, TL-13, TL-15, TL-07) — ví dụ cụ thể và bất biến chạy với hàng trăm bộ số.</summary>
public class SettlementCalculatorTests
{
    private static SettlementInput Input(long revenue, long cost, decimal operatorPct = 7, decimal taxPct = 0, params (long, long)[] shares)
        => new(revenue, cost, operatorPct, taxPct, shares);

    [Fact]
    public void Pool_duong_tru_thu_lao_roi_chia_theo_von_khop_tung_dong()
    {
        // Doanh thu 150 tr, chi phí khoá 100 tr → Pool 50 tr; thù lao 7% = 3,5 tr; chia 46,5 tr theo vốn 30/50/20
        var r = SettlementCalculator.Calculate(Input(150_000_000, 100_000_000, 7, 0, (1, 30_000_000), (2, 50_000_000), (3, 20_000_000)));

        Assert.Equal(50_000_000, r.RevenuePool);
        Assert.Equal(3_500_000, r.OperatorRemuneration);
        Assert.Equal(46_500_000, r.Distributable);
        Assert.Equal([13_950_000L, 23_250_000L, 9_300_000L], r.Lines.Select(l => l.ProfitShare));
        Assert.Equal(r.Distributable, r.Lines.Sum(l => l.ProfitShare));
        Assert.Equal([43_950_000L, 73_250_000L, 29_300_000L], r.Lines.Select(l => l.NetPayout));
        Assert.Equal(0, r.UncoveredLoss);
    }

    [Fact]
    public void Thu_lao_lam_tron_xuong_va_phan_le_chia_bang_largest_remainder()
    {
        // Pool 1.000.001 đ, thù lao 7% = 70.000,07 → 70.000; còn 930.001 chia 3 người bằng nhau
        var r = SettlementCalculator.Calculate(Input(2_000_001, 1_000_000, 7, 0, (1, 1_000_000), (2, 1_000_000), (3, 1_000_000)));

        Assert.Equal(70_000, r.OperatorRemuneration);
        Assert.Equal(930_001, r.Lines.Sum(l => l.ProfitShare));
        Assert.Equal([310_001L, 310_000L, 310_000L], r.Lines.Select(l => l.ProfitShare));
    }

    [Fact]
    public void Pool_am_khong_co_thu_lao_lo_chia_theo_von()
    {
        // Doanh thu 70 tr, chi phí 100 tr → Pool −30 tr, chia lỗ theo vốn 60/40
        var r = SettlementCalculator.Calculate(Input(70_000_000, 100_000_000, 7, 5, (1, 60_000_000), (2, 40_000_000)));

        Assert.Equal(-30_000_000, r.RevenuePool);
        Assert.Equal(0, r.OperatorRemuneration);
        Assert.Equal([-18_000_000L, -12_000_000L], r.Lines.Select(l => l.ProfitShare));
        Assert.Equal([42_000_000L, 28_000_000L], r.Lines.Select(l => l.NetPayout));
        Assert.Equal(0, r.TaxTotal); // lỗ thì không có khoản khấu trừ
    }

    [Fact]
    public void Lo_vuot_tong_von_moi_nguoi_mat_het_von_phan_vuot_khong_chia_cho_nha_dau_tu()
    {
        // Doanh thu 0, chi phí 100 tr, vốn chỉ 80 tr → mỗi người mất đúng vốn của mình; 20 tr lỗ vượt không ai trong số nhà đầu tư chịu
        var r = SettlementCalculator.Calculate(Input(0, 100_000_000, 7, 0, (1, 50_000_000), (2, 30_000_000)));

        Assert.Equal([-50_000_000L, -30_000_000L], r.Lines.Select(l => l.ProfitShare));
        Assert.All(r.Lines, l => Assert.Equal(0, l.NetPayout));
        Assert.Equal(20_000_000, r.UncoveredLoss);
    }

    [Fact]
    public void Khau_tru_thue_tren_phan_chia_duong_lam_tron_xuong()
    {
        var r = SettlementCalculator.Calculate(Input(110_000_333, 100_000_000, 5, 5, (1, 1), (2, 2)));

        // Pool 10.000.333; thù lao 5% = 500.016; chia 9.500.317 theo 1:2 → 3.166.772 / 6.333.545; thuế 5% làm tròn xuống
        Assert.Equal([3_166_772L, 6_333_545L], r.Lines.Select(l => l.ProfitShare));
        Assert.Equal([158_338L, 316_677L], r.Lines.Select(l => l.TaxWithheld));
        Assert.Equal(r.Lines.Sum(l => l.TaxWithheld), r.TaxTotal);
        Assert.All(r.Lines, l => Assert.Equal(l.Capital + l.ProfitShare - l.TaxWithheld, l.NetPayout));
    }

    [Fact]
    public void Lo_100_nha_dau_tu_tinh_nhanh()
    {
        var shares = Enumerable.Range(1, 100).Select(i => ((long)i, (long)(1_000_000 + i * 37_000))).ToArray();
        var started = System.Diagnostics.Stopwatch.StartNew();
        var r = SettlementCalculator.Calculate(Input(123_456_789, 98_765_432, 7, 5, shares));
        Assert.True(started.Elapsed < TimeSpan.FromSeconds(1));
        Assert.Equal(r.Distributable, r.Lines.Sum(l => l.ProfitShare));
    }

    // Bất biến bảo toàn: tổng phần chia − lỗ vượt trần = đúng phần đem chia, với mọi doanh thu, chi phí, cơ cấu vốn
    [Property]
    public Property Tong_phan_chia_khop_tung_dong(NonNegativeInt revenueK, PositiveInt costK, NonEmptyArray<PositiveInt> capitalK)
    {
        var shares = capitalK.Get.Take(50).Select((c, i) => ((long)i + 1, (long)c.Get * 1_000)).ToArray();
        var r = SettlementCalculator.Calculate(Input((long)revenueK.Get * 1_000 + 7, (long)costK.Get * 1_000, 7, 5, shares));
        return (r.Lines.Sum(l => l.ProfitShare) - r.UncoveredLoss == r.Distributable).ToProperty();
    }

    // Trần lỗ: không ai mất quá vốn của mình, số nhận về không bao giờ âm
    [Property]
    public Property Khong_ai_lo_qua_von(NonNegativeInt revenueK, PositiveInt costK, NonEmptyArray<PositiveInt> capitalK)
    {
        var shares = capitalK.Get.Take(50).Select((c, i) => ((long)i + 1, (long)c.Get * 1_000)).ToArray();
        var r = SettlementCalculator.Calculate(Input((long)revenueK.Get * 1_000, (long)costK.Get * 1_000, 10, 5, shares));
        return r.Lines.All(l => l.Capital + l.ProfitShare >= 0 && l.NetPayout >= 0 && l.TaxWithheld >= 0).ToProperty();
    }

    // Thù lao chỉ có khi Pool dương và không bao giờ vượt Pool
    [Property]
    public Property Thu_lao_chi_tren_pool_duong(NonNegativeInt revenueK, PositiveInt costK)
    {
        var r = SettlementCalculator.Calculate(Input((long)revenueK.Get * 1_000, (long)costK.Get * 1_000, 10, 0, (1, 1_000_000)));
        return (r.RevenuePool > 0 ? r.OperatorRemuneration >= 0 && r.OperatorRemuneration <= r.RevenuePool : r.OperatorRemuneration == 0).ToProperty();
    }
